  "formulas": [
    {
      "id": "formula_ex1_monomi",
      "latex": "6a^2b^3c, \\quad 9a^3b^2, \\quad 12ab^4",
      "alt_text": "I monomi sono 6a^2b^3c, 9a^3b^2, 12ab^4.",
      "expression": "6*a**2*b**3*c, 9*a**3*b**2, 12*a*b**4"
    },
    {
      "id": "formula_ex1_mcd_sol",
      "latex": "\\text{MCD}(6a^2b^3c, 9a^3b^2, 12ab^4) = 3ab^2",
      "alt_text": "Il Massimo Comune Divisore è 3ab^2.",
      "expression": "3*a*b**2"
    },
    {
      "id": "formula_ex1_mcm_sol",
      "latex": "\\text{mcm}(6a^2b^3c, 9a^3b^2, 12ab^4) = 36a^3b^4c",
      "alt_text": "Il minimo comune multiplo è 36a^3b^4c.",
      "expression": "36*a**3*b**4*c"
    },
    {
      "id": "formula_ex2_expression",
      "latex": "(3x^2y) \\cdot (2xy^2) - (10x^3y^3) : (5x) + (xy)^3",
      "alt_text": "L'espressione è (3x^2y) per (2xy^2) meno (10x^3y^3) diviso (5x) più (xy) al cubo.",
      "expression": "(3*x**2*y) * (2*x*y**2) - (10*x**3*y**3) / (5*x) + (x*y)**3"
    },
    {
      "id": "formula_ex2_step1_t",
      "latex": "= 6x^3y^3 - 2x^2y^3 + x^3y^3",
      "alt_text": "Il primo passaggio della soluzione è 6x^3y^3 meno 2x^2y^3 più x^3y^3.",
      "expression": "6*x**3*y**3 - 2*x**2*y**3 + x**3*y**3"
    },
    {
      "id": "formula_ex2_step2_t",
      "latex": "= 7x^3y^3 - 2x^2y^3",
      "alt_text": "Il risultato è 7x^3y^3 meno 2x^2y^3.",
      "expression": "7*x**3*y**3 - 2*x**2*y**3"
    },
    {
      "id": "formula_ex3_expression",
      "latex": "[ (2a^2b)^3 : (4a^4b) ] \\cdot (3ab^2) - 5a^2b^4",
      "alt_text": "L'espressione è [ (2a^2b) al cubo diviso (4a^4b) ] per (3ab^2) meno 5a^2b^4.",
      "expression": "((2*a**2*b)**3 / (4*a**4*b)) * (3*a*b**2) - 5*a**2*b**4"
    },
    {
      "id": "formula_ex3_step1_t",
      "latex": "= [ 8a^6b^3 : 4a^4b ] \\cdot (3ab^2) - 5a^2b^4",
      "alt_text": "Il primo passaggio è [ 8a^6b^3 diviso 4a^4b ] per (3ab^2) meno 5a^2b^4.",
      "expression": "(8*a**6*b**3 / (4*a**4*b)) * (3*a*b**2) - 5*a**2*b**4"
    },
    {
      "id": "formula_ex3_step2_t",
      "latex": "= [ 2a^2b^2 ] \\cdot (3ab^2) - 5a^2b^4",
      "alt_text": "Il secondo passaggio è [ 2a^2b^2 ] per (3ab^2) meno 5a^2b^4.",
      "expression": "(2*a**2*b**2) * (3*a*b**2) - 5*a**2*b**4"
    },
    {
      "id": "formula_ex3_step3_t",
      "latex": "= 6a^3b^4 - 5a^2b^4",
      "alt_text": "Il risultato è 6a^3b^4 meno 5a^2b^4.",
      "expression": "6*a**3*b**4 - 5*a**2*b**4"
    },
    {
      "id": "formula_ex4_expression",
      "latex": "(3x + 2y)^2",
      "alt_text": "L'espressione è (3x + 2y) al quadrato.",
      "expression": "(3*x + 2*y)**2"
    },
    {
      "id": "formula_ex4_step1_t",
      "latex": "= (3x)^2 + 2(3x)(2y) + (2y)^2",
      "alt_text": "Il primo passaggio è (3x) al quadrato più 2 volte (3x)(2y) più (2y) al quadrato.",
      "expression": "(3*x)**2 + 2*(3*x)*(2*y) + (2*y)**2"
    },
    {
      "id": "formula_ex4_step2_t",
      "latex": "= 9x^2 + 12xy + 4y^2",
      "alt_text": "Il risultato è 9x^2 più 12xy più 4y^2.",
      "expression": "9*x**2 + 12*x*y + 4*y**2"
    },
    {
      "id": "formula_ex5_expression",
      "latex": "\\left(\\frac{1}{2}a - \\frac{3}{4}b\\right)^2",
      "alt_text": "L'espressione è (1/2 a meno 3/4 b) al quadrato.",
      "expression": "(Rational(1,2)*a - Rational(3,4)*b)**2"
    },
    {
      "id": "formula_ex5_step1_t",
      "latex": "= \\left(\\frac{1}{2}a\\right)^2 - 2\\left(\\frac{1}{2}a\\right)\\left(\\frac{3}{4}b\\right) + \\left(\\frac{3}{4}b\\right)^2",
      "alt_text": "Il primo passaggio è (1/2 a) al quadrato meno 2 volte (1/2 a)(3/4 b) più (3/4 b) al quadrato.",
      "expression": "(Rational(1,2)*a)**2 - 2*(Rational(1,2)*a)*(Rational(3,4)*b) + (Rational(3,4)*b)**2"
    },
    {
      "id": "formula_ex5_step2_t",
      "latex": "= \\frac{1}{4}a^2 - \\frac{3}{4}ab + \\frac{9}{16}b^2",
      "alt_text": "Il risultato è 1/4 a^2 meno 3/4 ab più 9/16 b^2.",
      "expression": "Rational(1,4)*a**2 - Rational(3,4)*a*b + Rational(9,16)*b**2"
    },
    {
      "id": "formula_ex6_expression",
      "latex": "(5m - 3n)(5m + 3n)",
      "alt_text": "L'espressione è (5m meno 3n) per (5m più 3n).",
      "expression": "(5*m - 3*n)*(5*m + 3*n)"
    },
    {
      "id": "formula_ex6_step1_t",
      "latex": "= (5m)^2 - (3n)^2",
      "alt_text": "Il primo passaggio è (5m) al quadrato meno (3n) al quadrato.",
      "expression": "(5*m)**2 - (3*n)**2"
    },
    {
      "id": "formula_ex6_step2_t",
      "latex": "= 25m^2 - 9n^2",
      "alt_text": "Il risultato è 25m^2 meno 9n^2.",
      "expression": "25*m**2 - 9*n**2"
    },
    {
      "id": "formula_ex7_expression",
      "latex": "(4x + 7)(4x - 7)",
      "alt_text": "L'espressione è (4x più 7) per (4x meno 7).",
      "expression": "(4*x + 7)*(4*x - 7)"
    },
    {
      "id": "formula_ex7_step1_t",
      "latex": "= (4x)^2 - (7)^2",
      "alt_text": "Il primo passaggio è (4x) al quadrato meno 7 al quadrato.",
      "expression": "(4*x)**2 - 7**2"
    },
    {
      "id": "formula_ex7_step2_t",
      "latex": "= 16x^2 - 49",
      "alt_text": "Il risultato è 16x^2 meno 49.",
      "expression": "16*x**2 - 49"
    }
