    {
      "id": "formula_ex1_sol_mcm_final",
      "latex": "\\text{mcm monomi} = 720x^4y^4z^3",
      "alt_text": "mcm dei monomi è 720x^4y^4z^3",
      "expression": "720 * x^4 * y^4 * z^3"
    },
    {
      "id": "formula_ex2_expr",
      "latex": "(4x^3y^2)^2 : (-2x^4y^3) \\cdot (xy) - 5x^3y^2",
      "alt_text": "Espressione: (4x^3y^2)^2 diviso (-2x^4y^3) per (xy) meno 5x^3y^2",
      "expression": "(4*x^3*y^2)^2 / (-2*x^4*y^3) * (x*y) - 5*x^3*y^2"
    },
    {
      "id": "formula_ex2_sol_step1",
      "latex": "=(16x^6y^4) : (-2x^4y^3) \\cdot (xy) - 5x^3y^2",
      "alt_text": "Passaggio 1: 16x^6y^4 diviso (-2x^4y^3) per (xy) meno 5x^3y^2",
      "expression": "(16*x^6*y^4) / (-2*x^4*y^3) * (x*y) - 5*x^3*y^2"
    },
    {
      "id": "formula_ex2_sol_step2",
      "latex": "=(-8x^2y) \\cdot (xy) - 5x^3y^2",
      "alt_text": "Passaggio 2: -8x^2y per (xy) meno 5x^3y^2",
      "expression": "(-8*x^2*y) * (x*y) - 5*x^3*y^2"
    },
    {
      "id": "formula_ex2_sol_step3",
      "latex": "=-8x^3y^2 - 5x^3y^2",
      "alt_text": "Passaggio 3: -8x^3y^2 meno 5x^3y^2",
      "expression": "-8*x^3*y^2 - 5*x^3*y^2"
    },
    {
      "id": "formula_ex2_sol_step4",
      "latex": "=-13x^3y^2",
      "alt_text": "Passaggio 4: -13x^3y^2",
      "expression": "-13*x^3*y^2"
    },
    {
      "id": "formula_ex3_expr",
      "latex": "\\left[ \\left(\\frac{1}{2} x^2y\\right)^3 \\cdot (-4x^2y) \\right] : \\left(\\frac{1}{4} x^5y^3\\right) - (3xy^2)^2 : (-xy)",
      "alt_text": "Espressione: [ (1/2 x^2y)^3 per (-4x^2y) ] diviso (1/4 x^5y^3) meno (3xy^2)^2 diviso (-xy)",
      "expression": "((1/2 * x^2 * y)^3 * (-4 * x^2 * y)) / (1/4 * x^5 * y^3) - (3 * x * y^2)^2 / (-x * y)"
    },
    {
      "id": "formula_ex3_sol_step1",
      "latex": "= \\left[ \\left(\\frac{1}{8} x^6y^3\\right) \\cdot (-4x^2y) \\right] : \\left(\\frac{1}{4} x^5y^3\\right) - (9x^2y^4) : (-xy)",
      "alt_text": "Passaggio 1: [ (1/8 x^6y^3) per (-4x^2y) ] diviso (1/4 x^5y^3) meno (9x^2y^4) diviso (-xy)",
      "expression": "((1/8 * x^6 * y^3) * (-4 * x^2 * y)) / (1/4 * x^5 * y^3) - (9 * x^2 * y^4) / (-x * y)"
    },
    {
      "id": "formula_ex3_sol_step2",
      "latex": "= \\left[ -\\frac{1}{2} x^8y^4 \\right] : \\left(\\frac{1}{4} x^5y^3\\right) - (-9xy^3)",
      "alt_text": "Passaggio 2: [ -1/2 x^8y^4 ] diviso (1/4 x^5y^3) meno (-9xy^3)",
      "expression": "(-1/2 * x^8 * y^4) / (1/4 * x^5 * y^3) - (-9 * x * y^3)"
    },
    {
      "id": "formula_ex3_sol_step3",
      "latex": "= \\left(-\\frac{1}{2} \\cdot 4\\right) x^{8-5}y^{4-3} + 9xy^3",
      "alt_text": "Passaggio 3: (-1/2 per 4) x elevato (8 meno 5) y elevato (4 meno 3) più 9xy^3",
      "expression": "(-1/2 * 4) * x^(8-5) * y^(4-3) + 9*x*y^3"
    },
    {
      "id": "formula_ex3_sol_step4",
      "latex": "= -2x^3y + 9xy^3",
      "alt_text": "Passaggio 4: -2x^3y più 9xy^3",
      "expression": "-2*x^3*y + 9*x*y^3"
    },
    {
      "id": "formula_ex4_expr",
      "latex": "(3x + 4y)^2",
      "alt_text": "Quadrato di binomio: (3x + 4y) al quadrato",
      "expression": "(3*x + 4*y)^2"
    },
    {
      "id": "formula_ex4_sol_step1",
      "latex": "=(3x)^2 + 2(3x)(4y) + (4y)^2",
      "alt_text": "Passaggio 1: (3x)^2 più 2(3x)(4y) più (4y)^2",
      "expression": "(3*x)^2 + 2*(3*x)*(4*y) + (4*y)^2"
    },
    {
      "id": "formula_ex4_sol_step2",
      "latex": "=9x^2 + 24xy + 16y^2",
      "alt_text": "Passaggio 2: 9x^2 più 24xy più 16y^2",
      "expression": "9*x^2 + 24*x*y + 16*y^2"
    },
