      "expression": "1/4 * a^4 - 3/4 * a^2 * b + 9/16 * b^2"
    },
    {
      "id": "formula_ex6_expr",
      "latex": "(5x - 2y)(5x + 2y)",
      "alt_text": "Prodotto notevole: (5x - 2y) per (5x + 2y)",
      "expression": "(5*x - 2*y) * (5*x + 2*y)"
    },
    {
