      "alt_text": "Passaggio 1: (5x)^2 meno (2y)^2",
      "expression": "(5*x)^2 - (2*y)^2"
    },
    {
      "id": "formula_ex6_sol_step2",
      "latex": "=25x^2 - 4y^2",
      "alt_text": "Passaggio 2: 25x^2 meno 4y^2",
      "expression": "25*x^2 - 4*y^2"
    },
    {
      "id": "formula_ex7_expr",
      "latex": "(3a - b)(3a + b) - (2a + b)^2 + 5ab",
