  "formulas": [
    {
      "id": "formula_ex1_monomi",
      "latex": "M_1 = 6a^2b^3c \\quad M_2 = 9a^3b^2d",
      "alt_text": "Monomials M1 = 6a^2b^3c, M2 = 9a^3b^2d",
      "expression": "6*a^2*b^3*c, 9*a^3*b^2*d"
    },
    {
      "id": "formula_ex1_sol_mcd",
      "latex": "\\text{MCD}(6a^2b^3c, 9a^3b^2d) = 3a^2b^2",
      "alt_text": "MCD of 6a^2b^3c and 9a^3b^2d is 3a^2b^2",
      "expression": "gcd(6*a^2*b^3*c, 9*a^3*b^2*d) = 3*a^2*b^2"
    },
    {
      "id": "formula_ex1_sol_mcm",
      "latex": "\\text{mcm}(6a^2b^3c, 9a^3b^2d) = 18a^3b^3cd",
      "alt_text": "lcm of 6a^2b^3c and 9a^3b^2d is 18a^3b^3cd",
      "expression": "lcm(6*a^2*b^3*c, 9*a^3*b^2*d) = 18*a^3*b^3*c*d"
    },
    {
      "id": "formula_ex2_expr",
      "latex": "3x^2y \\cdot (-2xy^3) + \\frac{10x^3y^4}{5x} - (x^2y^2 \\cdot (-3y^2))",
      "alt_text": "Expression: 3x^2y multiplied by -2xy^3, plus 10x^3y^4 divided by 5x, minus (x^2y^2 multiplied by -3y^2)",
      "expression": "3*x^2*y * (-2*x*y^3) + (10*x^3*y^4)/(5*x) - (x^2*y^2 * (-3*y^2))"
    },
    {
      "id": "formula_ex2_sol_step1",
      "latex": "= -6x^3y^4 + 2x^2y^4 - (-3x^2y^4)",
      "alt_text": "Step 1: -6x^3y^4 + 2x^2y^4 - (-3x^2y^4)",
      "expression": "-6*x^3*y^4 + 2*x^2*y^4 - (-3*x^2*y^4)"
    },
    {
      "id": "formula_ex2_sol_step2",
      "latex": "= -6x^3y^4 + 2x^2y^4 + 3x^2y^4 = -6x^3y^4 + 5x^2y^4",
      "alt_text": "Step 2: -6x^3y^4 + 2x^2y^4 + 3x^2y^4 = -6x^3y^4 + 5x^2y^4",
      "expression": "-6*x^3*y^4 + 2*x^2*y^4 + 3*x^2*y^4 = -6*x^3*y^4 + 5*x^2*y^4"
    },
    {
      "id": "formula_ex3_expr",
      "latex": "\\left[ (2a^2b)^3 : (4ab)^2 \\right] \\cdot \\left( -\\frac{2}{3} ab \\right) - (-a^5b^4)",
      "alt_text": "Expression: [ (2a^2b)^3 divided by (4ab)^2 ] multiplied by (-2/3 ab) minus (-a^5b^4)",
      "expression": "((2*a^2*b)^3 / (4*a*b)^2) * (-2/3 * a*b) - (-a^5*b^4)"
    },
    {
      "id": "formula_ex3_sol_step1",
      "latex": "= \\left[ (8a^6b^3) : (16a^2b^2) \\right] \\cdot \\left( -\\frac{2}{3} ab \\right) + a^5b^4",
      "alt_text": "Step 1: [ (8a^6b^3) divided by (16a^2b^2) ] multiplied by (-2/3 ab) plus a^5b^4",
      "expression": "((8*a^6*b^3) / (16*a^2*b^2)) * (-2/3 * a*b) + a^5*b^4"
    },
    {
      "id": "formula_ex3_sol_step2",
      "latex": "= \\left( \\frac{1}{2}a^4b \\right) \\cdot \\left( -\\frac{2}{3} ab \\right) + a^5b^4",
      "alt_text": "Step 2: (1/2 a^4b) multiplied by (-2/3 ab) plus a^5b^4",
      "expression": "(1/2*a^4*b) * (-2/3 * a*b) + a^5*b^4"
    },
    {
      "id": "formula_ex3_sol_step3",
      "latex": "= -\\frac{1}{3}a^5b^2 + a^5b^4",
      "alt_text": "Step 3: -1/3 a^5b^2 + a^5b^4",
      "expression": "-1/3*a^5*b^2 + a^5*b^4"
    },
    {
      "id": "formula_ex4_expr",
      "latex": "(2x^2 + 3y)^2 - 4x^3(x + 2y)",
      "alt_text": "Expression: (2x^2 + 3y)^2 minus 4x^3(x + 2y)",
      "expression": "(2*x^2 + 3*y)^2 - 4*x^3*(x + 2*y)"
    },
    {
      "id": "formula_ex4_sol_step1",
      "latex": "= (4x^4 + 12x^2y + 9y^2) - (4x^4 + 8x^3y)",
      "alt_text": "Step 1: (4x^4 + 12x^2y + 9y^2) minus (4x^4 + 8x^3y)",
      "expression": "(4*x^4 + 12*x^2*y + 9*y^2) - (4*x^4 + 8*x^3*y)"
    },
    {
      "id": "formula_ex4_sol_step2",
      "latex": "= 4x^4 + 12x^2y + 9y^2 - 4x^4 - 8x^3y",
      "alt_text": "Step 2: 4x^4 + 12x^2y + 9y^2 - 4x^4 - 8x^3y",
      "expression": "4*x^4 + 12*x^2*y + 9*y^2 - 4*x^4 - 8*x^3*y"
    },
    {
      "id": "formula_ex4_sol_step3",
      "latex": "= 12x^2y + 9y^2 - 8x^3y",
      "alt_text": "Step 3: 12x^2y + 9y^2 - 8x^3y",
      "expression": "12*x^2*y + 9*y^2 - 8*x^3*y"
    },
    {
      "id": "formula_ex5_expr",
      "latex": "\\left( \\frac{1}{2}a - \\frac{2}{3}b^2 \\right)^2 + \\frac{4}{9}b^3(b - 3a)",
      "alt_text": "Expression: (1/2 a - 2/3 b^2)^2 plus 4/9 b^3(b - 3a)",
      "expression": "(1/2*a - 2/3*b^2)^2 + 4/9*b^3*(b - 3*a)"
    },
    {
      "id": "formula_ex5_sol_step1",
      "latex": "= \\left( \\frac{1}{4}a^2 - \\frac{2}{3}ab^2 + \\frac{4}{9}b^4 \\right) + \\left( \\frac{4}{9}b^4 - \\frac{4}{3}ab^3 \\right)",
      "alt_text": "Step 1: (1/4 a^2 - 2/3 ab^2 + 4/9 b^4) plus (4/9 b^4 - 4/3 ab^3)",
      "expression": "(1/4*a^2 - 2/3*a*b^2 + 4/9*b^4) + (4/9*b^4 - 4/3*a*b^3)"
    },
    {
      "id": "formula_ex5_sol_step2",
      "latex": "= \\frac{1}{4}a^2 - \\frac{2}{3}ab^2 + \\frac{4}{9}b^4 + \\frac{4}{9}b^4 - \\frac{4}{3}ab^3",
      "alt_text": "Step 2: 1/4 a^2 - 2/3 ab^2 + 4/9 b^4 + 4/9 b^4 - 4/3 ab^3",
      "expression": "1/4*a^2 - 2/3*a*b^2 + 4/9*b^4 + 4/9*b^4 - 4/3*a*b^3"
    },
    {
      "id": "formula_ex5_sol_step3",
      "latex": "= \\frac{1}{4}a^2 - \\frac{2}{3}ab^2 + \\frac{8}{9}b^4 - \\frac{4}{3}ab^3",
      "alt_text": "Step 3: 1/4 a^2 - 2/3 ab^2 + 8/9 b^4 - 4/3 ab^3",
      "expression": "1/4*a^2 - 2/3*a*b^2 + 8/9*b^4 - 4/3*a*b^3"
    },
    {
      "id": "formula_ex6_expr",
      "latex": "(3x - 2y)(3x + 2y) - (9x^2 - 5y^2)",
      "alt_text": "Expression: (3x - 2y)(3x + 2y) minus (9x^2 - 5y^2)",
      "expression": "(3*x - 2*y)*(3*x + 2*y) - (9*x^2 - 5*y^2)"
    },
    {
      "id": "formula_ex6_sol_step1",
      "latex": "= (9x^2 - 4y^2) - (9x^2 - 5y^2)",
      "alt_text": "Step 1: (9x^2 - 4y^2) minus (9x^2 - 5y^2)",
      "expression": "(9*x^2 - 4*y^2) - (9*x^2 - 5*y^2)"
    },
    {
      "id": "formula_ex6_sol_step2",
      "latex": "= 9x^2 - 4y^2 - 9x^2 + 5y^2",
      "alt_text": "Step 2: 9x^2 - 4y^2 - 9x^2 + 5y^2",
      "expression": "9*x^2 - 4*y^2 - 9*x^2 + 5*y^2"
    },
    {
      "id": "formula_ex6_sol_step3",
      "latex": "= y^2",
      "alt_text": "Step 3: y^2",
      "expression": "y^2"
