        {
          "kind": "text",
          "value": ", "
        },
        {
          "kind": "formula",
          "value": "b=-5"
        },
        {
          "kind": "text",
          "value": ", "
        },
        {
          "kind": "formula",
          "value": "c=3"
        },
        {
          "kind": "text",
          "value": ". Calcoliamo il discriminante "
        },
        {
          "kind": "formula",
          "value": "\\Delta"
        },
        {
          "kind": "text",
          "value": "."
        }
      ]
    },
    {
