    {
      "id": "text_ex3_s_step2",
      "segments": [
        {
          "kind": "text",
          "value": "Identifichiamo i coefficienti dell'equazione in forma intera: "
        },
        {
          "kind": "formula",
          "value": "a=2"
        },
        {
          "kind": "text",
          "value": ", "
        },
        {
          "kind": "formula",
          "value": "b=3"
