    },
    {
      "id": "text_ex4_s_step1",
      "segments": [
        {
          "kind": "text",
          "value": "Consideriamo l'equazione associata "
        },
        {
          "kind": "formula",
          "value": "x^2 - 4x + 3 = 0"
        },
        {
          "kind": "text",
          "value": ". Troviamo le sue radici."
        }
      ]
    },
    {
      "id": "text_ex4_s_step3",
      "segments": [
        {
          "kind": "text",
          "value": "La parabola "
        },
        {
          "kind": "formula",
          "value": "y = x^2 - 4x + 3"
        },
        {
          "kind": "text",
          "value": " ha concavità rivolta verso l'alto (il coefficiente di "
