        {
          "kind": "formula",
          "value": "x^2"
        },
        {
          "kind": "text",
          "value": " è positivo). Poiché la disequazione richiede "
        },
        {
          "kind": "formula",
          "value": "> 0"
        },
        {
          "kind": "text",
          "value": ", la soluzione è l'intervallo esterno alle radici."
        }
      ]
    },
    {
      "id": "text_ex4_s_final",
      "segments": [
        {
          "kind": "text",
          "value": "La soluzione della disequazione è "
        },
        {
          "kind": "formula",
          "value": "x < 1 \\text{ o } x > 3"
        },
        {
          "kind": "text",
          "value": ", che in notazione di intervalli è "
        },
        {
          "kind": "formula",
          "value": "(-\\infty, 1) \\cup (3, +\\infty)"
        },
        {
          "kind": "text",
          "value": "."
        }
      ]
    },
    {
      "id": "text_ex5_q",
      "segments": [
        {
          "kind": "text",
          "value": "Risolvi la seguente disequazione di secondo grado a coefficienti frazionari:"
