    {
      "id": "text_ex5_s_step4",
      "segments": [
        {
          "kind": "text",
          "value": "La parabola "
        },
        {
          "kind": "formula",
          "value": "y = 4x^2 - 6x + 1"
        },
        {
          "kind": "text",
          "value": " ha concavità rivolta verso l'alto. Poiché la disequazione richiede "
        },
        {
          "kind": "formula",
          "value": "\\le 0"
        },
        {
          "kind": "text",
          "value": ", la soluzione è l'intervallo interno alle radici, inclusi gli estremi."
        }
      ]
    },
    {
      "id": "text_ex5_s_final",
      "segments": [
        {
          "kind": "text",
          "value": "La soluzione della disequazione è "
        },
        {
          "kind": "formula",
          "value": "\\frac{3 - \\sqrt{5}}{4} \\le x \\le \\frac{3 + \\sqrt{5}}{4}"
        },
        {
          "kind": "text",
          "value": ", che in notazione di intervalli è "
        },
        {
          "kind": "formula",
          "value": "\\left[ \\frac{3 - \\sqrt{5}}{4}, \\frac{3 + \\sqrt{5}}{4} \\right]"
        },
        {
          "kind": "text",
          "value": "."
        }
      ]
    },
    {
      "id": "text_ex6_q",
      "segments": [
        {
          "kind": "text",
          "value": "Dato l'intervallo, rappresentalo graficamente sulla retta reale e scrivilo in forma di disuguaglianza."
        }
      ]
    },
    {
      "id": "text_ex6_s_inequality",
      "segments": [
