      "segments": [
        {
          "kind": "text",
          "value": "Risolvi la seguente disequazione di secondo grado a coefficienti frazionari (non fratta):"
        }
      ]
    },
    {
      "id": "text_ex7_s_step1",
      "segments": [
        {
          "kind": "text",
          "value": "Per prima cosa, riordiniamo i termini della disequazione e portiamo tutto a un lato, in modo da avere 0 dall'altra parte."
