    {
      "id": "text_ex7_s_final",
      "segments": [
        {
          "kind": "text",
          "value": "La parabola "
        },
        {
          "kind": "formula",
          "value": "y = x^2 - 5x - 2"
        },
        {
          "kind": "text",
          "value": " ha concavità rivolta verso l'alto (il coefficiente di "
        },
        {
          "kind": "formula",
          "value": "x^2"
        },
        {
          "kind": "text",
          "value": " è positivo). Poiché la disequazione richiede "
