  "formulas": [
    {
      "id": "formula_ex1_q",
      "latex": "\\frac{2}{3}x - \\frac{1}{2} = \\frac{1}{6}x + \\frac{5}{3}",
      "alt_text": "Due terzi x meno un mezzo uguale un sesto x più cinque terzi",
      "expression": "2/3*x - 1/2 = 1/6*x + 5/3"
    },
    {
      "id": "formula_ex1_s_step1",
      "latex": "4x - 3 = x + 10",
      "alt_text": "Quattro x meno tre uguale x più dieci",
      "expression": "4*x - 3 = x + 10"
    },
    {
      "id": "formula_ex1_s_step2",
      "latex": "3x = 13",
      "alt_text": "Tre x uguale tredici",
      "expression": "3*x = 13"
    },
    {
      "id": "formula_ex1_s_step3",
      "latex": "x = \\frac{13}{3}",
      "alt_text": "x uguale tredici terzi",
      "expression": "x = 13/3"
    },
    {
      "id": "formula_ex2_q",
      "latex": "2x^2 - 5x + 3 = 0",
      "alt_text": "Due x al quadrato meno cinque x più tre uguale zero",
      "expression": "2*x^2 - 5*x + 3 = 0"
    },
    {
      "id": "formula_ex2_s_step2",
      "latex": "\\Delta = (-5)^2 - 4(2)(3) = 25 - 24 = 1",
      "alt_text": "Delta uguale meno cinque al quadrato meno quattro per due per tre uguale venticinque meno ventiquattro uguale uno",
      "expression": "(-5)^2 - 4*2*3 = 1"
    },
    {
      "id": "formula_ex2_s_step3",
      "latex": "x = \\frac{-(-5) \\pm \\sqrt{1}}{2(2)} = \\frac{5 \\pm 1}{4} \\Rightarrow x_1 = 1, x_2 = \\frac{3}{2}",
      "alt_text": "x uguale meno meno cinque più o meno radice di uno fratto due per due uguale cinque più o meno uno fratto quattro, quindi x uno uguale uno, x due uguale tre mezzi",
      "expression": "(-(-5) + sqrt(1))/(2*2) = 3/2, (-(-5) - sqrt(1))/(2*2) = 1"
    },
    {
      "id": "formula_ex3_q",
      "latex": "\\frac{1}{3}x^2 + \\frac{1}{2}x - \\frac{1}{6} = 0",
      "alt_text": "Un terzo x al quadrato più un mezzo x meno un sesto uguale zero",
      "expression": "1/3*x^2 + 1/2*x - 1/6 = 0"
    },
    {
      "id": "formula_ex3_s_step1",
      "latex": "2x^2 + 3x - 1 = 0",
      "alt_text": "Due x al quadrato più tre x meno uno uguale zero",
      "expression": "2*x^2 + 3*x - 1 = 0"
    },
    {
      "id": "formula_ex3_s_step3",
      "latex": "\\Delta = (3)^2 - 4(2)(-1) = 9 + 8 = 17 \\Rightarrow x = \\frac{-3 \\pm \\sqrt{17}}{4}",
      "alt_text": "Delta uguale tre al quadrato meno quattro per due per meno uno uguale nove più otto uguale diciassette, quindi x uguale meno tre più o meno radice di diciassette fratto quattro",
      "expression": "(3)^2 - 4*2*(-1) = 17"
    },
    {
      "id": "formula_ex4_q",
      "latex": "x^2 - 4x + 3 > 0",
      "alt_text": "x al quadrato meno quattro x più tre maggiore di zero",
      "expression": "x^2 - 4*x + 3 > 0"
    },
    {
      "id": "formula_ex4_s_step2",
      "latex": "x^2 - 4x + 3 = 0 \\Rightarrow (x-1)(x-3) = 0 \\Rightarrow x_1 = 1, x_2 = 3",
      "alt_text": "x al quadrato meno quattro x più tre uguale zero implica x meno uno per x meno tre uguale zero, quindi x uno uguale uno, x due uguale tre",
      "expression": "solve(x^2 - 4*x + 3 = 0, x)"
    },
    {
      "id": "formula_ex4_s_step4",
      "latex": "x < 1 \\text{ o } x > 3",
      "alt_text": "x minore di uno o x maggiore di tre",
      "expression": "x < 1 or x > 3"
    },
    {
      "id": "formula_ex5_q",
      "latex": "\\frac{1}{2}x^2 - \\frac{3}{4}x + \\frac{1}{8} \\le 0",
      "alt_text": "Un mezzo x al quadrato meno tre quarti x più un ottavo minore o uguale a zero",
      "expression": "1/2*x^2 - 3/4*x + 1/8 <= 0"
    },
    {
      "id": "formula_ex5_s_step1",
      "latex": "4x^2 - 6x + 1 \\le 0",
      "alt_text": "Quattro x al quadrato meno sei x più uno minore o uguale a zero",
      "expression": "4*x^2 - 6*x + 1 <= 0"
    },
    {
      "id": "formula_ex5_s_step3",
      "latex": "\\Delta = (-6)^2 - 4(4)(1) = 36 - 16 = 20 \\Rightarrow x = \\frac{6 \\pm \\sqrt{20}}{8} = \\frac{6 \\pm 2\\sqrt{5}}{8} = \\frac{3 \\pm \\sqrt{5}}{4}",
      "alt_text": "Delta uguale meno sei al quadrato meno quattro per quattro per uno uguale trentasei meno sedici uguale venti, quindi x uguale sei più o meno radice di venti fratto otto uguale sei più o meno due radice di cinque fratto otto uguale tre più o meno radice di cinque fratto quattro",
      "expression": "(-6)^2 - 4*4*1 = 20"
    },
    {
      "id": "formula_ex5_s_step5",
      "latex": "\\frac{3 - \\sqrt{5}}{4} \\le x \\le \\frac{3 + \\sqrt{5}}{4}",
      "alt_text": "Tre meno radice di cinque fratto quattro minore o uguale a x minore o uguale a tre più radice di cinque fratto quattro",
      "expression": "(3 - sqrt(5))/4 <= x <= (3 + sqrt(5))/4"
    },
    {
      "id": "formula_ex6_q_interval_notation",
      "latex": "[-3, 5)",
      "alt_text": "Intervallo chiuso a meno tre e aperto a cinque",
      "expression": "[-3, 5)"
    },
    {
      "id": "formula_ex6_s_inequality_form",
      "latex": "-3 \\le x < 5",
      "alt_text": "Meno tre minore o uguale a x minore di cinque",
      "expression": "-3 <= x < 5"
    },
    {
      "id": "formula_ex7_q",
      "latex": "\\frac{1}{4}x^2 - \\frac{1}{2}x > \\frac{3}{4}x + \\frac{1}{2}",
      "alt_text": "Un quarto x al quadrato meno un mezzo x maggiore di tre quarti x più un mezzo",
      "expression": "1/4*x^2 - 1/2*x > 3/4*x + 1/2"
    },
    {
      "id": "formula_ex7_s_step2",
      "latex": "\\frac{1}{4}x^2 - \\frac{1}{2}x - \\frac{3}{4}x - \\frac{1}{2} > 0 \\Rightarrow \\frac{1}{4}x^2 - \\frac{5}{4}x - \\frac{1}{2} > 0",
      "alt_text": "Un quarto x al quadrato meno un mezzo x meno tre quarti x meno un mezzo maggiore di zero implica un quarto x al quadrato meno cinque quarti x meno un mezzo maggiore di zero",
      "expression": "1/4*x^2 - 1/2*x - 3/4*x - 1/2 > 0"
    },
    {
      "id": "formula_ex7_s_step4",
      "latex": "x^2 - 5x - 2 > 0",
      "alt_text": "x al quadrato meno cinque x meno due maggiore di zero",
      "expression": "x^2 - 5*x - 2 > 0"
    },
    {
      "id": "formula_ex7_s_step6",
      "latex": "\\Delta = (-5)^2 - 4(1)(-2) = 25 + 8 = 33 \\Rightarrow x = \\frac{5 \\pm \\sqrt{33}}{2}",
      "alt_text": "Delta uguale meno cinque al quadrato meno quattro per uno per meno due uguale venticinque più otto uguale trentatré, quindi x uguale cinque più o meno radice di trentatré fratto due",
      "expression": "(-5)^2 - 4*1*(-2) = 33"
    }
  ],
